class Solution {
    public long maxScore(int[][] edges) {
        int n = edges.length;
        List<Integer>[] ch = new List[n];
        for (int i = 0; i < n; i++) ch[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) ch[edges[i][0]].add(i);
        int[] order = new int[n];
        int head = 0, tail = 0;
        order[tail++] = 0;
        while (head < tail) for (int c : ch[order[head++]]) order[tail++] = c;
        long[] free = new long[n], best = new long[n]; // free: no child edge of v chosen
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            long sum = 0, gain = 0;
            for (int c : ch[v]) sum += best[c];
            for (int c : ch[v]) gain = Math.max(gain, edges[c][1] + free[c] - best[c]);
            free[v] = sum;
            best[v] = sum + gain;
        }
        return best[0];
    }
}
